const base="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const rs=await Promise.all([
  tools.exec_command({cmd:"nl -ba AlgebraicJacobian/Picard/Pic0FiniteStageOverlapBaseChange.lean | sed -n '1,240p'",workdir:base,yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"\"$HORIZON_GIT\" diff -- AlgebraicJacobian/Picard/Pic0FiniteStageOverlapBaseChange.lean",workdir:base,yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"\"$HORIZON_GIT\" status --short -- AlgebraicJacobian/Picard/Pic0FiniteStageOverlapBaseChange.lean",workdir:base,yield_time_ms:10000,max_output_tokens:5000})
]);
text(`FILE\n${rs[0].output}\nDIFF\n${rs[1].output}\nSTATUS\n${rs[2].output}`);

const t = ALL_TOOLS.find(x=>x.name==="mcp__lean_lsp__lean_diagnostic_messages");
if(!t) throw new Error("Lean diagnostic tool unavailable");
const r = await tools.mcp__lean_lsp__lean_diagnostic_messages({
  file_path:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0FiniteStageOverlapBaseChange.lean",
  timeout_s:60
});
for (const c of (r.content||[])) {
  if (c.type==="text") text(c.text); else if (c.type==="image") image(c);
}

